function tagsForBiz(b) {
  const base = (b.tags || []).slice();
  const cat = (b.cat || '').toLowerCase();
  if (cat.includes('services')) base.push('services business');
  if (cat.includes('manufacturing')) base.push('manufacturing business');
  if (cat.includes('education')) base.push('education business');
  if (cat.includes('food')) base.push('food business');
  return Array.from(new Set(base));
}

function buildAnswer(b) {
  return (
'## Direct Answer\n\n' +
'Start a ' + b.type + ' business in 2027 by combining the 4 operator moves below, sized to a startup cost of ' + b.startup + ' and a year-1 revenue band of ' + b.y1 + '. The dominant unit-economic risk in this category is the one called out in the bottom line.\n\n' +
'## The Operator Playbook\n\n' +
b.moves.map((m, i) => '**' + (i+1) + '. ' + m.split('—')[0].split(',')[0].trim().slice(0, 80) + '.** ' + m).join('\n\n') + '\n\n' +
'## Unit Economics (year-1 ballpark)\n\n' +
'| Lever | Range |\n' +
'|---|---|\n' +
'| Startup cost | ' + b.startup + ' |\n' +
'| Year-1 revenue | ' + b.y1 + ' |\n' +
'| Customer acquisition cost | ' + b.cac + ' |\n' +
'| Annual contract / lifetime value | ' + b.acv + ' |\n' +
'| Customer profile | ' + b.market + ' |\n' +
'| Category | ' + b.cat + ' |\n\n' +
'## Operator Diagram\n\n' +
'```mermaid\nflowchart LR\n  L["Lead source"] --> Q["Qualified buyer"]\n  Q --> O["Offer / package"]\n  O --> D["Delivery"]\n  D --> R["Retention / referral"]\n  R --> L\n```\n\n' +
'## Bottom Line\n\n' +
b.risk + ' Operators who plan around this constraint from day 1 — not as an afterthought in year 2 — are the ones who get to a healthy year-3 P&L in this category.'
  );
}

(async () => {
  let written = 0, skipped = 0;
  const idx = (await store.get('_index.json', { type: 'json' })) || { entries: [] };
  const existingIds = new Set(idx.entries.map(e => String(e.id)));
  for (let i = 0; i < BIZ.length; i++) {
    const b = BIZ[i];
    const id = 'q' + (9560 + i);
    if (existingIds.has(id)) { skipped++; console.log('skip existing', id); continue; }
    const question = 'How do you start a ' + b.type + ' business in 2027?';
    const answer = buildAnswer(b);
    if (answer.length < 800) { console.error('answer too short for', id, answer.length); continue; }
    const now = Date.now();
    const entry = {
      id,
      question,
      answer,
      tags: tagsForBiz(b),
      sources: [],
      quality_score: 5,
      polish_history: [],
      created_at: now,
      polished_at: null,
      was_indexed_at: null,
    };
    await store.setJSON('answers/' + id + '.json', entry);
    idx.entries.push({
      id,
      question,
      tags: tagsForBiz(b),
      quality_score: 5,
      polished_at: null,
      was_indexed_at: null,
      last_modified_ms: now,
    });
    written++;
    console.log('+ ' + id + ' ' + b.type);
  }
  await store.setJSON('_index.json', idx);
  console.log('=== BATCH DONE === written=' + written + ' skipped=' + skipped + ' total entries now=' + idx.entries.length);
})().catch(e => { console.error('FATAL', e); process.exit(1); });
